sketch:
// Potentiometer — turn the knob and watch the voltage A0 sees.
//
// A potentiometer is a variable divider: the wiper (SIG) taps value/1023 of the
// way from GND to VCC, so 512 reads about half the supply. Drag the knob on the
// canvas — or slide it in the properties strip, which stays live while the sketch
// runs — and the readings on the serial monitor follow.

void setup() {
  Serial.begin(9600);
}

void loop() {
  int raw = analogRead(A0);
  int volts = map(raw, 0, 1023, 0, 500);   // centivolts, to keep the maths in ints
  Serial.print("A0 = ");
  Serial.print(raw);
  Serial.print("/1023  ~");
  Serial.print(volts / 100);
  Serial.print('.');
  Serial.print(volts % 100);
  Serial.println(" V");
  delay(200);
}
